<script>document.addEventListener('DOMContentLoaded',()=>{const c=document.getElementById('ciclo'),n=document.getElementById('nivel'),g=document.getElementById('grado'),s=document.getElementById('seccion'),v=document.getElementById('visibilidad'),d=document.getElementById('destinatarios');function filtrar(select,atributo,valor){[...select.options].forEach(o=>{if(!o.value)return;o.hidden=o.disabled=o.dataset[atributo]!==valor});if(select.selectedOptions[0]?.disabled)select.value=''}function actualizar(){d.style.display=v.value==='DESTINATARIOS'?'':'none';n.required=v.value==='DESTINATARIOS';g.disabled=!n.value||v.value!=='DESTINATARIOS';filtrar(g,'nivel',n.value);s.disabled=!g.value||!c.value||v.value!=='DESTINATARIOS';[...s.options].forEach(o=>{if(!o.value)return;o.hidden=o.disabled=o.dataset.grado!==g.value||o.dataset.ciclo!==c.value});if(s.selectedOptions[0]?.disabled)s.value=''}n.addEventListener('change',()=>{g.value='';s.value='';actualizar()});g.addEventListener('change',()=>{s.value='';actualizar()});c.addEventListener('change',()=>{s.value='';actualizar()});v.addEventListener('change',actualizar);actualizar()})</script>
